// Local videos. Two sources, merged: video links pasted into the Video column of any sheet row,
// and the channel list in data/videos.csv. Newest first.
import { readTable, profiles, href } from './data';

export type Video = {
  id: string; title: string; display: string; duration: string; source: string;
  tour: boolean; thumb: string; place: string; placeName: string;
};

const ytId = (u: string) => (String(u || '').match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/|live\/))([\w-]{11})/) || [])[1] || '';
const norm = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '');
// A tidy title for the page: no hashtags or emoji. The full title stays on YouTube.
const clean = (t: string) => t.replace(/#\w+/g, '').replace(/[\p{Extended_Pictographic}\u200d\ufe0f\u{1F1E6}-\u{1F1FF}]/gu, '').replace(/\s+/g, ' ').replace(/\s*\|\s*(?=\||$)/g, '').replace(/\s*[|]\s*$/, '').trim();

const places = profiles.filter((p) => ['Business', 'Place'].includes(p.type) && norm(p.name).length >= 7);
const findPlace = (title: string, named: string) => {
  const direct = named ? profiles.find((p) => p.name === named) : undefined;
  if (direct) return direct;
  const t = norm(title);
  return places.filter((p) => t.includes(norm(p.name))).sort((a, b) => norm(b.name).length - norm(a.name).length)[0];
};
const make = (id: string, title: string, duration: string, source: string, named: string): Video => {
  const p = findPlace(title, named);
  return { id, title, display: clean(title) || title, duration, source, tour: /walking tour|tour|spotlight/i.test(title), thumb: 'https://i.ytimg.com/vi/' + id + '/hqdefault.jpg', place: p ? href(p) : '', placeName: p ? p.name : '' };
};

// Links pasted on a sheet row (Profiles or Content), shown first.
const fromSheet: Video[] = [];
const seen = new Set<string>();
for (const r of [...readTable('profiles.csv').map((x) => ({ title: x.name, named: x.name, video: x.video })), ...readTable('content.csv').map((x) => ({ title: x.title, named: x.profile, video: x.video }))]) {
  for (const u of (r.video || '').split(/[\n|;,\s]+/)) {
    const id = ytId(u); if (!id || seen.has(id)) continue;
    seen.add(id); fromSheet.push(make(id, r.title || r.named, '', 'Sheet', r.named));
  }
}
const fromChannel: Video[] = readTable('videos.csv').filter((r) => r.id && r.title && !seen.has(r.id)).map((r) => { seen.add(r.id); return make(r.id, r.title, r.duration, r.source, r.profile); });
export const videos: Video[] = [...fromSheet, ...fromChannel];

__files.src/components/VideoCard.astro:
---
const { v } = Astro.props;
---
<div class="card vcard" data-kind={v.tour ? 'tour' : 'food'}>
  <button type="button" class="vthumb" data-id={v.id} data-title={v.display} aria-label={'Play ' + v.display}>
    <img src={v.thumb} alt="" loading="lazy" />
    <span class="vplay" aria-hidden="true"></span>
    {v.duration && <span class="vdur">{v.duration}</span>}
  </button>
  <div class="vbody">
    <h4 style="margin-bottom:6px">{v.display}</h4>
    {v.place && <p class="meta" style="font-size:15px">At <a href={v.place}>{v.placeName}</a></p>}
  </div>
</div>
<style is:global>
  .vthumb { position: relative; display: block; width: 100%; aspect-ratio: 16 / 9; border: 0; padding: 0; background: #000; cursor: pointer; overflow: hidden; border-radius: 12px 12px 0 0; }
  .vthumb img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .25s; }
  .vthumb:hover img, .vthumb:focus-visible img { transform: scale(1.04); }
  .vthumb:focus-visible { outline: 3px solid var(--gold); outline-offset: -3px; }
  .vplay { position: absolute; left: 50%; top: 50%; width: 64px; height: 64px; margin: -32px 0 0 -32px; border-radius: 50%; background: rgba(29, 26, 109, .88); }
  .vplay::after { content: ""; position: absolute; left: 25px; top: 19px; border-left: 20px solid #fff; border-top: 13px solid transparent; border-bottom: 13px solid transparent; }
  .vdur { position: absolute; right: 10px; bottom: 10px; background: rgba(0, 0, 0, .78); color: #fff; font-size: 13px; font-weight: 700; padding: 2px 8px; border-radius: 6px; }
  .vcard { overflow: hidden; }
  .vcard .vbody { padding: 18px 20px 20px; }
  .vcard iframe { width: 100%; aspect-ratio: 16 / 9; border: 0; display: block; }
</style>

__files.src/pages/videos.astro:
---
import Base from '../layouts/Base.astro';
import VideoCard from '../components/VideoCard.astro';
import VideoScript from '../components/VideoScript.astro';
import '../styles/pages.css';
import { config } from '../config';
import { videos } from '../lib/videos';
const latest = videos[0];
const rest = videos.slice(1);
const tours = rest.filter((v) => v.tour).length;
const food = rest.length - tours;
const suggest = 'mailto:traditionlocal@gmail.com?subject=Video%20idea';
---
<Base title="Videos" active="More" description="Neighborhood walks, coffee runs, and honest reviews from Tradition Local.">
  <section class="band hero">
    <div class="wrap">
      <p class="eyebrow">Local videos</p>
      <h1 style="margin-bottom:16px;max-width:900px">Houston, one neighborhood at a time.</h1>
      <p class="lead" style="margin-bottom:28px;max-width:720px">Walking tours, coffee runs, and honest reviews from Sara and Dillon, filmed around Greater Houston.</p>
      <div style="display:flex;gap:12px;flex-wrap:wrap"><a class="btn" href={config.youtube} rel="noopener">Watch on YouTube</a><a class="btn line" href={suggest}>Suggest a place to film</a></div>
    </div>
  </section>

  {videos.length === 0 && (
    <section class="band"><div class="wrap"><div class="card pad"><b>Videos are coming soon.</b><p class="meta" style="margin-top:4px">In the meantime, you can find us on YouTube.</p></div></div></section>
  )}

  {latest && (
    <section class="band" id="latest">
      <div class="wrap">
        <p class="eyebrow">Latest</p><h2 style="margin-bottom:24px">Newest from the channel.</h2>
        <div style="max-width:860px"><VideoCard v={latest} /></div>
      </div>
    </section>
  )}

  {rest.length > 0 && (
    <section class="band tint" id="all-videos">
      <div class="wrap">
        <p class="eyebrow">All videos</p><h2 style="margin-bottom:20px">Keep watching.</h2>
        <div class="tabs" id="v-tabs" style="margin-bottom:12px">
          <button class="chip on" data-k="" aria-pressed="true">All</button>
          {food > 0 && <button class="chip" data-k="food" aria-pressed="false">Food and coffee ({food})</button>}
          {tours > 0 && <button class="chip" data-k="tour" aria-pressed="false">Walking tours ({tours})</button>}
        </div>
        <p class="meta" id="v-count" style="margin-bottom:20px">{rest.length} videos</p>
        <div class="grid g3" id="v-grid">{rest.map((v) => <VideoCard v={v} />)}</div>
      </div>
    </section>
  )}

  <section class="band butter">
    <div class="wrap" style="display:flex;justify-content:space-between;align-items:center;gap:32px;flex-wrap:wrap">
      <div style="max-width:700px"><h3 style="margin-bottom:8px">Know a place we should film?</h3><p style="font-size:17px">Tell us about a spot you love, and it might be our next video.</p></div>
      <div style="display:flex;gap:12px;flex-wrap:wrap"><a class="btn" href={suggest}>Suggest a place</a><a class="btn line" href={config.youtube} rel="noopener">Watch on YouTube</a></div>
    </div>
  </section>
  <VideoScript />
  <script is:inline>
    (function () {
      var tabs = document.getElementById('v-tabs'); if (!tabs) return;
      var cards = [].slice.call(document.querySelectorAll('#v-grid .vcard'));
      tabs.addEventListener('click', function (e) {
        var b = e.target.closest('button'); if (!b) return;
        [].forEach.call(tabs.children, function (c) { c.classList.toggle('on', c === b); c.setAttribute('aria-pressed', c === b ? 'true' : 'false'); });
        var k = b.dataset.k, n = 0;
        cards.forEach(function (c) { var ok = !k || c.dataset.kind === k; c.classList.toggle('hidden', !ok); if (ok) n++; });
        document.getElementById('v-count').textContent = n + (n === 1 ? ' video' : ' videos');
      });
    })();
  </script>
</Base>

